#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<long long> L(n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        cin >> L[i];
        total += L[i];
    }

    if (total % 2 != 0) {
        cout << 'N' << '\n';
        return 0;
    }

    long long half = total / 2;

    // prefix[i] = arco cumulativo até a árvore i (árvore 0 tem prefixo 0)
    vector<long long> pref(n);
    pref[0] = 0;
    for (int i = 1; i < n; i++) pref[i] = pref[i-1] + L[i-1];

    unordered_set<long long> s;
    s.reserve(n * 2);
    s.max_load_factor(0.7);
    for (int i = 0; i < n; i++) s.insert(pref[i]);

    long long countPairs = 0;
    for (int i = 0; i < n; i++) {
        long long want = pref[i] + half;
        if (want >= total) want -= total;
        if (s.count(want)) countPairs++;
    }

    // cada par de árvores antipodais é contado duas vezes;
    // um retângulo precisa de dois pares diametrais distintos (4 árvores)
    cout << (countPairs >= 4 ? 'S' : 'N') << '\n';

    return 0;
}
